import React, { useState } from 'react';
import { X, Check } from 'lucide-react';

const steps = [
  { id: 1, label: 'Hãng xe', placeholder: 'Chọn hãng xe', type: 'select', options: ['Toyota', 'Honda', 'Kia', 'Hyundai', 'Mazda', 'Ford', 'VinFast'] },
  { id: 2, label: 'Dòng xe', placeholder: 'Chọn dòng xe', type: 'select', options: ['Vios', 'Camry', 'City', 'Cerato', 'CX-5'] },
  { id: 3, label: 'Đời xe', placeholder: 'Chọn đời xe', type: 'select', options: ['2018', '2019', '2020', '2021', '2022', '2023', '2024'] },
  { id: 4, label: 'Phiên bản', placeholder: 'Chọn phiên bản', type: 'select', options: ['1.5 AT', '1.5 MT', '2.0 AT', 'Luxury'] },
  { id: 5, label: 'Công tơ mét', placeholder: 'Nhập số công tơ mét (km)', type: 'input' },
  { id: 6, label: 'Khi nào bạn muốn bắt đầu bán xe?', placeholder: 'Chọn thời gian', type: 'select', options: ['Trong vòng 1 tuần', 'Trong tháng này', 'Chưa xác định'] },
];

const ValuationModal = ({ isOpen, onClose }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [formData, setFormData] = useState({});

  if (!isOpen) return null;

  const handleNext = () => {
    if (currentStep < steps.length) {
      setCurrentStep(prev => prev + 1);
    } else {
      // Finish and close or redirect
      alert('Định giá thành công! Dữ liệu của bạn: ' + JSON.stringify(formData));
      onClose();
    }
  };

  const handleBack = () => {
    if (currentStep > 1) {
      setCurrentStep(prev => prev - 1);
    }
  };

  const currentStepData = steps.find(s => s.id === currentStep);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
      {/* Modal Box */}
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl flex flex-col mx-4 md:mx-auto min-h-[550px] relative overflow-hidden animate-in slide-in-from-bottom-10 md:zoom-in-95 duration-300">

        {/* Close Button */}
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-700 transition z-10"
        >
          <X size={24} />
        </button>

        <div className="flex flex-col md:flex-row flex-1 p-8 md:p-10">
          {/* LEFT SIDE - Stepper */}
          <div className="md:w-2/5 flex flex-col mb-8 md:mb-0 md:pr-10 relative">

            <div className="space-y-0 relative mt-4">
              {/* Connecting vertical line */}
              <div className="absolute left-4 top-4 bottom-8 w-px bg-gray-200 pointer-events-none"></div>

              {steps.map((step, index) => {
                const isActive = step.id === currentStep;
                const isPassed = step.id < currentStep;

                return (
                  <div key={step.id} className={`flex items-start gap-4 cursor-pointer relative z-10 ${index !== steps.length - 1 ? 'pb-8' : ''}`} onClick={() => step.id < currentStep && setCurrentStep(step.id)}>
                    {/* Circle */}
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 transition-all duration-300 ${isActive ? 'bg-[#22c55e] text-white shadow-md scale-110' : isPassed ? 'bg-gray-200 text-gray-500' : 'bg-gray-200 text-white'}`}>
                      {isPassed ? <span className="text-sm font-bold text-gray-700">{step.id}</span> : isActive ? <span className="text-sm font-bold">{step.id}</span> : <span className="text-sm font-bold">{step.id}</span>}
                    </div>
                    {/* Label */}
                    <div className={`mt-1 transition-colors ${isActive ? 'text-gray-800 font-semibold' : 'text-gray-500 text-sm'}`}>
                      {step.label}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* RIGHT SIDE - Forms */}
          <div className="md:w-3/5 flex flex-col md:pl-10 md:border-l border-gray-100">
             <div className="flex-1 mt-8 md:mt-2 h-full flex flex-col justify-start">

                {/* Input field based on step type */}
                <div className="relative w-full">
                  {currentStepData.type === 'select' ? (
                    <select 
                      value={formData[currentStepData.id] || ''}
                      onChange={(e) => setFormData({...formData, [currentStepData.id]: e.target.value})}
                      className={`w-full appearance-none border-2 rounded-xl px-5 py-3.5 bg-white text-[15px] font-medium outline-none transition cursor-pointer hover:border-blue-300 focus:border-[#0096ff] focus:ring-4 focus:ring-blue-500/10 ${!formData[currentStepData.id] && isActive ? 'border-[#0096ff] shadow-sm text-gray-900' : 'border-gray-200 text-gray-700'}`}
                    >
                      <option value="" disabled>{currentStepData.placeholder}</option>
                      {currentStepData.options.map((opt, i) => (
                        <option key={i} value={opt} className="text-gray-900">{opt}</option>
                      ))}
                    </select>
                  ) : (
                    <input 
                      type="number" 
                      placeholder={currentStepData.placeholder} 
                      value={formData[currentStepData.id] || ''}
                      onChange={(e) => setFormData({...formData, [currentStepData.id]: e.target.value})}
                      className={`w-full border-2 rounded-xl px-5 py-3.5 bg-white text-[15px] font-medium outline-none transition focus:border-[#0096ff] focus:ring-4 focus:ring-blue-500/10 ${!formData[currentStepData.id] && isActive ? 'border-[#0096ff] shadow-sm text-gray-900' : 'border-gray-200 text-gray-700'}`}
                    />
                  )}
                  {currentStepData.type === 'select' && (
                     <div className="absolute top-1/2 right-4 -translate-y-1/2 pointer-events-none text-gray-400">
                       <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m6 9 6 6 6-6"/></svg>
                     </div>
                  )}
                </div>
             </div>

             {/* Footer Buttons */}
             <div className="flex items-center justify-end gap-3 mt-12">
               {currentStep > 1 && (
                 <button 
                   onClick={handleBack}
                   className="px-6 py-2.5 rounded-lg text-sm font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 transition"
                 >
                   Quay lại
                 </button>
               )}
               <button 
                 onClick={handleNext}
                 disabled={!formData[currentStepData.id]}
                 className="bg-[#0096ff] text-white px-8 py-2.5 rounded-xl text-[15px] font-bold hover:bg-blue-600 transition disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-blue-500/25 min-w-[120px]"
               >
                 {currentStep === steps.length ? 'Xác nhận' : 'Tiếp theo'}
               </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ValuationModal;
